class Ui
{
public:
    void beginFrame(int mouseX, int mouseY, bool mouseDown)
    {
        m_x = mouseX; m_y = mouseY;
        m_pressed = mouseDown && !m_wasDown;
        m_released = !mouseDown && m_wasDown;
        m_wasDown = mouseDown;
        m_hotThisFrame = 0;
    }

    bool button(int id, int x, int y, int w, int h)
    {
        const bool inside{ m_x >= x && m_x < x + w && m_y >= y && m_y < y + h };
        if (inside) m_hotThisFrame = id;                        // the last one drawn wins
        if (inside && m_pressed) m_active = id;                 // pressed on it: it becomes active
        return m_released && inside && m_active == id;          // released on it while active: a click
    }

    void endFrame()
    {
        m_hot = m_hotThisFrame;
        if (m_released) m_active = 0;                           // the press is over either way
    }

    int active() const { return m_active; }
    int hot() const { return m_hot; }

private:
    int m_x{ 0 }, m_y{ 0 };
    bool m_wasDown{ false }, m_pressed{ false }, m_released{ false };
    int m_active{ 0 };
    int m_hot{ 0 }, m_hotThisFrame{ 0 };
};

