// One frame: mouse state, then the two buttons A (id 1, at 0,0 size 10x10) and B (id 2, at 20,0 size 10x10).
static std::pair<bool, bool> frame(Ui& ui, int x, int y, bool down)
{
    ui.beginFrame(x, y, down);
    const bool a{ ui.button(1, 0, 0, 10, 10) };
    const bool b{ ui.button(2, 20, 0, 10, 10) };
    ui.endFrame();
    return { a, b };
}
TEST("press and release on a button clicks it")
{
    Ui ui;
    frame(ui, 5, 5, false);
    CHECK_EQ(ui.hot(), 1);
    CHECK(!frame(ui, 5, 5, true).first);
    CHECK_EQ(ui.active(), 1);
    CHECK(frame(ui, 5, 5, false).first);
    CHECK_EQ(ui.active(), 0);
}
TEST("release elsewhere does not click") { Ui ui; frame(ui, 5, 5, false); frame(ui, 5, 5, true); const auto r{ frame(ui, 50, 50, false) }; CHECK(!r.first); CHECK(!r.second); CHECK_EQ(ui.active(), 0); }
TEST("dragging onto another button does not click it") { Ui ui; frame(ui, 5, 5, false); frame(ui, 5, 5, true); frame(ui, 25, 5, true); CHECK_EQ(ui.active(), 1); const auto r{ frame(ui, 25, 5, false) }; CHECK(!r.second); CHECK(!r.first); }
TEST("pressing on empty space activates nothing") { Ui ui; frame(ui, 50, 50, false); frame(ui, 50, 50, true); CHECK_EQ(ui.active(), 0); frame(ui, 5, 5, true); CHECK_EQ(ui.active(), 0); }
TEST("holding the mouse down is not a new press") { Ui ui; frame(ui, 50, 50, true); frame(ui, 5, 5, true); CHECK_EQ(ui.active(), 0); CHECK(!frame(ui, 5, 5, false).first); }
TEST("edges") { Ui ui; frame(ui, 9, 9, false); CHECK_EQ(ui.hot(), 1); frame(ui, 10, 9, false); CHECK_EQ(ui.hot(), 0); }

